package com.campusnova.model;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity public class Faq { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Category category; @Column(nullable=false,length=500) private String question; @Column(nullable=false,length=5000) private String answer; @Column(length=1000) private String keywords; private boolean active=true; private LocalDateTime createdAt=LocalDateTime.now();
 public Faq(){} public Faq(Category c,String q,String a,String k){category=c;question=q;answer=a;keywords=k;} public Long getId(){return id;} public Category getCategory(){return category;} public void setCategory(Category c){category=c;} public String getQuestion(){return question;} public void setQuestion(String q){question=q;} public String getAnswer(){return answer;} public void setAnswer(String a){answer=a;} public String getKeywords(){return keywords;} public void setKeywords(String k){keywords=k;} public boolean isActive(){return active;} public void setActive(boolean a){active=a;} public LocalDateTime getCreatedAt(){return createdAt;} }
